/* @lc app=leetcode id=1000 lang=kotlin */ class Solution { fun mergeStones(stones: IntArray, k: Int): Int = if ((stones.size - 1) % (k - 1) != 0) -1 else IntArray(stones.size + 1).let { pre -> stones.indices.forEach { i -> pre[i + 1] = pre[i] + stones[i] }.run { Array(stones.size) { Array(stones.size) { IntArray(k + 1) { 1000000000 } } } }.let { dp -> stones.indices.forEach { i -> dp[i][i][1] = 0 }.run { (2..stones.size).forEach { len -> (0..stones.size - len).forEach { i -> (i + len - 1).let { j -> (2..k).forEach { m -> (i until j step (k - 1)).forEach { mid -> dp[i][j][m] = minOf(dp[i][j][m], dp[i][mid][1] + dp[mid + 1][j][m - 1]) } }.run { dp[i][j][1] = dp[i][j][k] + pre[j + 1] - pre[i] } } } } }.run { dp[0][stones.size - 1][1] } } } }